import{_ as p,r as s,o,c,e as n,a as r,s as l}from"./chunks/framework.CXcwiNg-.js";const m=JSON.parse('{"title":"Hash & Crypt - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Configuration","slug":"configuration","link":"#configuration","children":[]},{"level":2,"title":"Hashing","slug":"hashing","link":"#hashing","children":[{"level":4,"title":"Verifying a password against a hash","slug":"verifying-a-password-against-a-hash","link":"#verifying-a-password-against-a-hash","children":[]},{"level":4,"title":"Checking if a password needs to be rehashed","slug":"checking-if-a-password-needs-to-be-rehashed","link":"#checking-if-a-password-needs-to-be-rehashed","children":[]}]},{"level":2,"title":"Encryption","slug":"encryption","link":"#encryption","children":[{"level":4,"title":"Decrypting a value","slug":"decrypting-a-value","link":"#decrypting-a-value","children":[]}]}],"relativePath":"3.x/extend/services/hash-crypt.md","filePath":"3.x/extend/services/hash-crypt.md"}'),i={name:"3.x/extend/services/hash-crypt.md"};function h(d,a,u,k,g,y){const e=s("pre-heading"),t=s("post-heading");return o(),c("div",null,[n(e),a[0]||(a[0]=r("h1",null,"Hash & Crypt",-1)),n(t),a[1]||(a[1]=l(`<h2 id="configuration"><a href="#configuration" class="header-anchor">#</a> Configuration</h2><p>When you first installed October, a random key should have been generated for you. You can confirm this by checking the <code>key</code> option of your <code>config/app.php</code> configuration file. If the key remains unchanged, you should set it to a 32 character, random string. If this value is not properly set, all encrypted values will be insecure.</p><h2 id="hashing"><a href="#hashing" class="header-anchor">#</a> Hashing</h2><p>The <code>Hash</code> facade provides secure Bcrypt hashing for storing user passwords. Bcrypt is a great choice for hashing passwords because its &quot;work factor&quot; is adjustable, which means that the time it takes to generate a hash can be increased as hardware power increases.</p><p>You may hash a password by calling the <code>make</code> method on the <code>Hash</code> facade:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">User</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">password</span> <span class="token operator">=</span> <span class="token class-name static-context">Hash</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;mypassword&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Alternatively, models can implement the <a href="./../database/traits.html">Hashable trait</a> to automatically hash attributes.</p><h4 id="verifying-a-password-against-a-hash"><a href="#verifying-a-password-against-a-hash" class="header-anchor">#</a> Verifying a password against a hash</h4><p>The <code>check</code> method allows you to verify that a given plain-text string corresponds to a given hash.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Hash</span><span class="token operator">::</span><span class="token function">check</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;plain-text&#39;</span><span class="token punctuation">,</span> <span class="token variable">$hashedPassword</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// The passwords match...</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="checking-if-a-password-needs-to-be-rehashed"><a href="#checking-if-a-password-needs-to-be-rehashed" class="header-anchor">#</a> Checking if a password needs to be rehashed</h4><p>The <code>needsRehash</code> function allows you to determine if the work factor used by the hasher has changed since the password was hashed:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Hash</span><span class="token operator">::</span><span class="token function">needsRehash</span><span class="token punctuation">(</span><span class="token variable">$hashed</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$hashed</span> <span class="token operator">=</span> <span class="token class-name static-context">Hash</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;plain-text&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="encryption"><a href="#encryption" class="header-anchor">#</a> Encryption</h2><p>You may encrypt a value using the <code>Crypt</code> facade. All encrypted values are encrypted using OpenSSL and the <code>AES-256-CBC</code> cipher. Furthermore, all encrypted values are signed with a message authentication code (MAC) to detect any modifications to the encrypted string.</p><p>For example, we may use the <code>encrypt</code> method to encrypt a secret and store it on a <a href="./../database/model.html">database model</a>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">User</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">secret</span> <span class="token operator">=</span> <span class="token class-name static-context">Crypt</span><span class="token operator">::</span><span class="token function">encrypt</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;shhh no telling&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="decrypting-a-value"><a href="#decrypting-a-value" class="header-anchor">#</a> Decrypting a value</h4><p>Of course, you may decrypt values using the <code>decrypt</code> method on the <code>Crypt</code> facade. If the value can not be properly decrypted, such as when the MAC is invalid, an <code>Illuminate\\Contracts\\Encryption\\DecryptException</code> exception will be thrown:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">Illuminate<span class="token punctuation">\\</span>Contracts<span class="token punctuation">\\</span>Encryption<span class="token punctuation">\\</span>DecryptException</span><span class="token punctuation">;</span>

<span class="token keyword">try</span> <span class="token punctuation">{</span>
    <span class="token variable">$decrypted</span> <span class="token operator">=</span> <span class="token class-name static-context">Crypt</span><span class="token operator">::</span><span class="token function">decrypt</span><span class="token punctuation">(</span><span class="token variable">$encryptedValue</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token keyword">catch</span> <span class="token punctuation">(</span><span class="token class-name">DecryptException</span> <span class="token variable">$ex</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Alternatively, models can implement the <a href="./../database/traits.html">Encryptable trait</a> to automatically encrypt and decrypt attributes.</p>`,21))])}const v=p(i,[["render",h]]);export{m as __pageData,v as default};
